/**
 * Format a per-token price (USD) as a price per million tokens.
 * @param {string|number|null|undefined} p
 * @returns {string} "-", "var", or e.g. "$0.30"
 */
export function formatPrice(p) {
  if (p === null || p === undefined || p === "") return "-";

  let str = String(p).trim();
  const negative = str.startsWith("-");
  if (negative) str = str.slice(1);
  if (str === "" || isNaN(Number(str))) return negative ? "var" : "-";

  if (negative) return "var";

  // Scale by 1e6 using exact decimal string arithmetic to avoid float errors.
  const dot = str.indexOf(".");
  let digits = str.replace(".", "");
  const decimals = dot === -1 ? 0 : str.length - dot - 1;
  const shift = decimals - 6; // digits now represent value * 10^-shift

  let cents;
  if (shift <= 0) {
    // value = digits * 10^shift; convert to cents (x100) = digits * 10^(shift+2)
    const exp = shift + 2;
    if (exp <= 0) {
      cents = BigInt(digits) / 10n ** BigInt(-exp);
      // truncate is fine; value far below half a cent
    } else {
      cents = BigInt(digits) * 10n ** BigInt(exp);
    }
  } else {
    // more than 6 decimals: round to nearest after shifting
    const keep = digits.slice(0, digits.length - shift) || "0";
    const rest = digits.slice(digits.length - shift);
    const roundUp = rest.length > 0 && Number(rest[0]) >= 5;
    cents = BigInt(keep) + (roundUp ? 1n : 0n);
  }

  const dollars = Number(cents) / 100;
  return "$" + dollars.toFixed(2);
}
