  const shift = Number(exponentText) - fraction.length + 8;
  let cents;

  if (shift >= 0) {
    cents = BigInt(digits + "0".repeat(shift));
  } else {
    const cut = -shift;
    const kept = cut >= digits.length ? "0" : digits.slice(0, digits.length - cut);
    const discarded = cut >= digits.length
      ? digits.padStart(cut, "0")
      : digits.slice(digits.length - cut);
    cents = BigInt(kept || "0");
    if (discarded[0] >= "5") cents += 1n;
  }

  return `$${cents / 100n}.${String(cents % 100n).padStart(2, "0")}`;
