/**
 * Format a per-token price (USD) as a per-million-token price string.
 *
 * @param {string|number|null|undefined} p - Price in USD per token.
 * @returns {string} "-" when missing, "var" when negative (variable pricing),
 *                   otherwise e.g. "$0.30" for "0.0000003".
 */
export function formatPrice(p) {
  // Missing values.
  if (p === null || p === undefined || p === "") return "-";

  const n = Number(p);

  // Anything non-numeric is treated as missing.
  if (!Number.isFinite(n)) return "-";

  // A negative price means "variable".
  if (n < 0) return "var";

  // Convert per-token to per-million-token, rounded to whole cents to
  // avoid floating point artifacts (e.g. 0.0000025 -> 2.5, not 2.49...).
  const perMillion = n * 1e6;
  const cents = Math.round(perMillion * 100 + Number.EPSILON);

  return `$${(cents / 100).toFixed(2)}`;
}

export default formatPrice;
